#include <stdio.h>
#include <stdbool.h>

typedef struct {
    char type;
    int x;
} Record;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Record records[30];
    for (int i = 0; i < n; i++) {
        scanf(" %c %d", &records[i].type, &records[i].x);
    }

    int total_time[105] = {0};
    int last_received[105] = {0};
    bool waiting[105] = {false};
    bool present[105] = {false};

    int current_time = 0;

    for (int i = 0; i < n; i++) {
        char type = records[i].type;
        int x = records[i].x;

        if (type == 'R') {
            present[x] = true;
            waiting[x] = true;
            last_received[x] = current_time;
        } else if (type == 'E') {
            present[x] = true;
            waiting[x] = false;
            total_time[x] += (current_time - last_received[x]);
        }

        if (type == 'R' || type == 'E') {
            if (i + 1 < n) {
                if (records[i + 1].type == 'T') {
                    current_time += records[i + 1].x;
                } else {
                    current_time += 1;
                }
            }
        }
    }

    for (int i = 1; i <= 100; i++) {
        if (present[i]) {
            if (waiting[i]) {
                printf("%d -1\n", i);
            } else {
                printf("%d %d\n", i, total_time[i]);
            }
        }
    }

    return 0;
}
